// nisargadatta_te.dart
// Nisargadatta maharaj quotes and articles (Telugu)

import '../articlesquotes.dart';

final nisargadattaSaintTe = Saint(
  'nisargadatta',
  'Nisargadatta maharaj',
  'assets/images/nisargadatta.jpg',
  [
    'మీరు మీరనుకునేది కాదు. మీరు నిజంగా ఏమిటో తెలుసుకోండి.',
    'నిజమైనది మరణించదు, అప్రకృతమైనది ఎప్పుడూ జీవించలేదు.',
    'జ్ఞానం నాకు నేను శూన్యం అని చెబుతుంది. ప్రేమ నాకు నేను సమస్తం అని చెబుతుంది. ఈ రెండింటి మధ్య నా జీవితం ప్రవహిస్తుంది.',
    'నీవు పరమ సత్యం. చిన్న మనస్సుతో ఉండవద్దు.',
    'మీరు ఏమిటో తెలుసుకోవాలంటే, మీరు ఏమికాదో ముందుగా పరిశీలించి తెలుసుకోవాలి.',
    'మీలోని చైతన్యం, నాలోని చైతన్యం, బహిరంగంగా రెండు వేర్వేరు అనిపించినా, అవి ఒకటే, ఆ ఐక్యతను అన్వేషించండి, అదే ప్రేమ.',
    'మీరు మీను నిర్వచించుకునే స్వభావాన్ని వదిలించుకోవడమే అవసరం.',
    'మీరు మార్గమే లక్ష్యం అని, మీరు ఎప్పుడూ మార్గంలోనే ఉన్నారని, లక్ష్యాన్ని చేరుకోవడానికి కాదు, దాని అందం మరియు జ్ఞానాన్ని ఆస్వాదించడానికి అని తెలుసుకున్నప్పుడు, జీవితం ఒక కర్తవ్యంగా ఉండటం ఆపి సహజంగా మరియు సరళంగా మారుతుంది.',
    'మీరు శరీరం కాదు. మీరు మనస్సు కూడా కాదు. మీరు ఈ రెండూ కనిపించే చైతన్యం.',
    'మీ నిజమైన స్వరూపాన్ని తెలుసుకున్న క్షణంలో, మీరు ఏదికీ భయపడరు.',
    'మీరు ఇది లేదా అది చేస్తున్నట్లు ఊహించడం మానేసి, మీరు సమస్తానికి మూలం మరియు హృదయం అని గ్రహించగలుగుతారు.',
    'మీరు గ్రహించే ఏదీ మీది కాదు. మీరు గ్రహించే ఏదీ మీతో సంబంధం లేదు.',
    'సాంప్రదాయ ప్రమాణాలను విడిచిపెట్టండి. వాటిని సాంప్రదాయానుసరులకే వదిలేయండి.',
    'నీ నిజమైన నివాసం శూన్యతలో, అన్ని విషయాల లేనితనంలో ఉంది.',
    'నేను నా అంతరంలోకి చూసి నేను శూన్యం అని గ్రహించినప్పుడు, అది జ్ఞానం. నేను బాహ్య ప్రపంచంలోకి చూసి నేను సమస్తం అని గ్రహించినప్పుడు, అది ప్రేమ.',
    'మనసు అగాధాన్ని సృష్టిస్తుంది, హృదయం దానిని దాటుతుంది.',
    'మీరు ఏమనుకుంటున్నారో, మీరు అదేమీ కాదు.',
    'మీరు మీను ఒక వ్యక్తిగా భావిస్తారు, కానీ మీరు వ్యక్తిగా జన్మించలేదు.',
    'నిజానికి, మీరు ఒక వస్తువు కాదు, ఇతర వస్తువుల నుండి వేరుగా కూడా కాదు.',
    'నిజాన్వేషణ అన్నది అత్యంత ప్రమాదకరమైన ప్రయత్నం, ఎందుకంటే అది మీరు నివసిస్తున్న లోకాన్ని నాశనం చేస్తుంది.',
    'అన్ని విభజనలు, ప్రతి రకమైన పరాయితనం మరియు విభిన్నత అనేది అసత్యం.',
    'నీవు సమస్తాన్ని ఆవహించే చైతన్యానికి ఆవిర్భావం మరియు వ్యక్తీకరణ అయిన పరమ శక్తి.',
    'వ్యక్తిగతం రక్షణ అవసరం, నిజమైనది రక్షణ అవసరం లేదు.',
    'మీ స్వంత ఊహలే తప్ప మరేమీ మీను కలవరపెట్టలేవు.',
    'మీ స్వంత ఊహలే తప్ప మరేదీ మీకు క్షోభ కలిగించలేవని మీరు సంపూర్ణ నిశ్చయంతో తెలుసుకున్నప్పుడు, మీ కోరికలు మరియు భయాలను మీరు పట్టించుకోకుండా పోతారు.',
    'మీరు లోకంలో లేరు, లోకం మీలో ఉంది.',
    '"నేను ఉన్నాను" అనే భావన మీ సొంతం. మీరు దానిని విడిచిపెట్టలేరు, కానీ దానిని ఏదైనా అంశానికి అన్వయించవచ్చు, ఉదాహరణకు "నేను యువకుడిని", "నేను ధనవంతుడిని" అని.',
    'వేదన మరియు ఆనందం అనే రెండు తీరాల మధ్య జీవన నది ప్రవహిస్తుంది. మనసు జీవన ప్రవాహానికి అనుకూలంగా ప్రవహించకుండా, తీరాల వద్ద నిలిచిపోతేనే అది సమస్యగా మారుతుంది.',
    'తెలిసినది నుండి విముక్తి.',
    'మీ బలహీనత మీ ఈ లోకంలో జన్మించామని మీరు నమ్మిన నమ్మకంలోనే ఉంది.',
    'మోక్షం కోసం మనస్సును ఆశ్రయించవద్దు. బంధనంలోకి నిన్ను తీసుకువచ్చింది అదే మనస్సు.',
    'నిజమైన గురువు జీవితం స్వయంగా.',
    'నీవు దానిని పొందవలసిన అవసరం లేదు, ఎందుకంటే నీవే అది.',
    'ప్రేమ అంటుంది \'నేను సమస్తం\'. జ్ఞానం అంటుంది \'నేను శూన్యం\'. ఈ రెండింటి మధ్య, నా జీవితం ప్రవహిస్తుంది.',
    'మనసు, ఆత్మ, ఆత్మస్వరూపం అనే త్రిమూర్తులు పరిశీలించినప్పుడు ఏకత్వంగా మారుతాయి.',
    'ఉండిపో. నీ నిజస్వరూపం వెలుగులోకి రానివ్వు. ఆత్మాన్వేషణతో నీ మనసును కలవరపెట్టకు.',
    'మీ ఆత్మనే మీకు పరమ గురువు. బాహ్య గురువు కేవలం ఒక మైలురాయి మాత్రమే.',
    'మీ లోకంలో ప్రతి దానికి ఆరంభం మరియు ముగింపు ఉండాలి. అవి లేకపోతే, మీరు దానిని నిత్యమైనదిగా పిలుస్తారు.',
    'జ్ఞాని ఈ ప్రపంచాన్ని యథార్థంగా చూస్తాడు: తత్వంలో ఏకత్వం, రూపంలో వైవిధ్యం.',
    'కల్పనలేని చూపుతో చూడటం, వక్రీకరణలేని వినికిడి నేర్చుకోండి.',
    'మనస్సు మనస్సు ఉందని చెప్పేది మనస్సే. మోసపోవద్దు.',
    'నిజం మంచి ప్రవర్తనకు బహుమతి కాదు, లేదా కొన్ని పరీక్షలు ఉత్తీర్ణం కావడానికి బహుమానంగా కాదు.',
    'మీరు మానవుడని భావింపజేస్తున్నది మానవం కాదు.',
    'మీరు మీకోసమే ఒక జైలు నిర్మించడానికి ఎంతో శక్తిని వినియోగించారు. ఇప్పుడు దానిని కూల్చడానికి అంతే శక్తిని వినియోగించండి.',
    'మీరు ఆ వ్యక్తి కాదని అర్థం చేసుకోవాలంటే, ఆ వ్యక్తిని గమనించండి. ఆ వ్యక్తిని చైతన్యంలో ఒక వస్తువుగా చూడండి.',
    'శరీర-మనసుల గుర్తింపును విడిచిపెట్టడంలో ఏ కష్టం ఉంది? చివరికి, మీరు శరీర-మనసులు కాదు.',
    'మీరు మృతిని భయపడుతున్నారు ఎందుకంటే మీరు మీను మీరు తెలుసుకోలేదు. నిజమైన మీరు అమృతమయుడు.',
    'మీరు మీను సర్వముగా మరియు సర్వాన్నీ మించి తెలుసుకోవడాన్ని అడ్డుకునేది, స్మృతిపై ఆధారపడిన మనస్సు.',
    'మనసు కాలంలో ఉంటుంది, మనం కాలానికి అతీతం.',
    'భయం లేనప్పుడు, నీవే ప్రేమ స్వరూపం.',
    'మీరు మీరనుకున్నది మీరు కాదు. మీరు శరీరం కాదు, మనస్సు కాదు, వ్యక్తిత్వ భావం కాదు. ఈ సమస్తం ఉద్భవించి, లయమయ్యే నిత్య చైతన్యమే మీరు.',
    'మీరు మీను వ్యక్తిగా కాకుండా చైతన్యంగా తెలుసుకున్న క్షణం, అన్ని బాధలు ముగుస్తాయి. మిగిలేది శాంతి, అది అనుభవం కాదు, కానీ మీ సహజ స్థితి.',
    'శరీరం పుట్టకముందు, లోకం కనిపించకముందు, నీవు ఉన్నావు. అన్ని భావనలకు ముందున్న ఆ సత్త్వభావంలో నిలిచి, మిగతావన్నీ విడిచిపెట్టు.',
    '\'నేను ఉన్నాను\' అనేది మొదటి ద్వారం. దానితో స్థిరంగా ఉండండి. \'నేను ఉన్నాను\' కూడా కరిగిపోయినప్పుడు, పరమార్థం మాత్రమే మిగులుతుంది.',
    'మీరు లోకంలో లేరు; లోకం మీలో ఉంది. మీరు మీ చైతన్యంలో సమస్త బ్రహ్మాండాన్ని మోస్తున్నారు.',
    'మీరు ఏమిటో తెలుసుకోవాలంటే, మీరు ఏమికాదో ముందుగా పరిశీలించాలి. చూడగలిగేది, గ్రహించగలిగేది, అనుభవించగలిగేది ఏదైనా మీకాదు.',
    'నిజమైన ఆత్మను పొందాల్సిన అవసరం లేదు. మీరు మీ గురించి ఉన్న అన్ని తప్పుడు భావనలు విడిచిపెట్టినప్పుడు మీరు ఏమిటో అదే.',
    'మీరు మీను పరిమితమైనవాడిగా ఊహించుకుంటారు, ఆ పరిమితి వల్ల మీరు బాధపడతారు. నిజానికి, మీరు ఏమిటో దానికి ఎలాంటి సరిహద్దులు లేవు.',
    'మీరు శరీర-మనస్సుతో ఐక్యతను విడిచిపెట్టినప్పుడు, మీరు ఎప్పుడూ బంధించబడలేదని, ఎప్పుడూ కష్టంలో లేనని, ఎప్పుడూ అసంపూర్ణంగా లేనని తెలుసుకుంటారు.',
    'చైతన్యం వ్యక్తిగతం కాదు. వ్యక్తి చైతన్యంలో ప్రత్యక్షమవుతాడు, కానీ చైతన్యం వ్యక్తికి చెందదు.',
    'చైతన్యం తాత్కాలిక స్థితి మాత్రమే. అది కనిపిస్తుంది, మాయమవుతుంది. చైతన్యాన్ని తెలుసుకునేది దాని కంటే పరమమైనది.',
    'నిరాకారం తన గురించి అవగాహన కలిగి ఉండదు. చైతన్యం అనేది సముద్రంపై అలల వలె, నిరాకారంలో ఉద్భవించే ఒక ప్రక్రియ.',
    'మీరు చైతన్యాన్ని మీగా భావిస్తారు, కానీ చైతన్యమును కూడా గమనించబడుతుంది. చైతన్యాన్ని గమనించే ఆత్మను కనుగొనండి.',
    'శరీరం మరియు లోకం చైతన్యంతో కలసి ఉద్భవిస్తాయి. చైతన్యం లేకపోతే, లోకం కూడా ఉండదు.',
    'చైతన్యం కలిగే ముందు, అనుభవం లేదు, సమయం లేదు, స్థలం లేదు — అయినా, మీరు ఉన్నారు. అదే మీ నిజ స్వరూపం.',
    'చైతన్యం శరీరంపై ఆధారపడి ఉంటుంది, కానీ పరమాత్మ ఎటువంటి ఆధారాన్ని అవసరం లేదు. ఈ తేడాను తెలుసుకో.',
    'చైతన్యం మరణంలో లీనమైతే, మీరు నిజంగా ఏమిటో అది చనిపోదు, ఎందుకంటే అది ఎప్పుడూ జన్మించలేదు.',
    'నిరాకారాన్ని మాటలతో వ్యక్తం చేయలేము. ఏది చెప్పబడగలదో అది కేవలం చైతన్యంపై మాత్రమే.',
    'చైతన్య మూలాన్ని ఆశ్రయించి ఉండండి, అప్పుడు మీరు దానిని అధిగమిస్తారు.',
    'మీరు చైతన్యం కదలికను వాస్తవమని పొరపాటుచేస్తారు. వాస్తవం అనేది కదలని దాని.',
    'మీ ఏకైక సాధన \'నేను ఉన్నాను\' అనే భావనను పట్టుకోవడం, మిగతావన్నీ ఆత్మకాదని త్రోసిపుచ్చడం.',
    'ఏమి కనిపిస్తుందో మార్చడానికి ప్రయత్నించకండి. మీరు ఏమిటో అర్థం చేసుకోండి, అప్పుడు అన్నీ స్వయంగా మారిపోతాయి.',
    'ప్రయత్నం అవసరం, ప్రయత్నరహితతను కనుగొనేవరకు. ఆ తరువాత ప్రయత్నం కూడా విడిచిపోతుంది.',
    'ఆత్మవిచారణ ఒక మానసిక వ్యాయామం కాదు. ఇది ప్రత్యక్షమయ్యే ఏదితోనైనా తలపోకూడదనే స్థిరమైన నిరాకరణ.',
    'మీ ఆలోచనలను ఆకాశంలో తేలియాడే మేఘాలను చూసినట్లుగా పరిశీలించండి. వాటిని మీవిగా అనుకోకండి.',
    'మనస్సును అధిగమించేందుకు మనస్సు సహాయపడదు. దానిని అర్థం చేసుకుని దాని పైనికి వెళ్లాలి.',
    'మీరు మనసును పరిశీలించినప్పుడు, మీరు ఇప్పటికే దానిని దాటి ఉన్నారు.',
    'ఎంత సమయం పడుతుందో అడగకండి. మీ అన్వేషణలో నిజాయితీగా, నిబద్ధతతో ఉండండి.',
    'మనస్సును శుద్ధి చేయాల్సిన అవసరం లేదు. దానితో ఐక్యతను విడిచిపెట్టండి.',
    'నిశ్శబ్దం అనేది శబ్దం లేనిదని కాదు; అది గుర్తింపులేని స్థితి.',
    'వ్యక్తి అనేది జ్ఞాపకాలు, అలవాట్లు, మరియు శిక్షణల సమాహారం. మీరు ఆ సమాహారం కాదు.',
    'అహంకారం కేవలం ఒక ఆలోచన మాత్రమే — చైతన్యం స్వీకరించిన ఒక తప్పుడు కేంద్రం.',
    'మీరు \'నేను బాధపడుతున్నాను\' అని చెప్పినప్పుడు, ఈ \'నేను\' ఎవరో అన్వేషించండి. మీరు దానిని కనుగొనలేరు.',
    '\'నేనే కర్త\' అనే భావం బంధనం. అది పోయినప్పుడు, స్వేచ్ఛ ఉంటుంది.',
    'వ్యక్తిత్వం నిజస్వరూపం కాదు; అది చైతన్యం ధరించిన ఒక ముఖవిలాసం.',
    'మీరు మీను వ్యక్తిగా భావించేంతవరకు, మీరు భయంతో జీవిస్తారు.',
    'వ్యక్తిత్వ భావన శరీరంతో వస్తుంది, అది శరీరంతోనే ముగుస్తుంది.',
    'మీరు శూన్యతను భయపడి వ్యక్తిని పట్టుకుంటారు, కానీ ఆ శూన్యతే శాంతి.',
    'వ్యక్తి లీనమయ్యినప్పుడు, మిగిలేది శూన్యత కాదు, పూర్ణత.',
    'అహంకారం నిరంతరతను కోరుకుంటుంది; కానీ వాస్తవానికి అలాంటిది లేదు.',
    'అన్ని కష్టాలు గుర్తింపులోంచి పుట్టినవే. మీరు తాత్కాలికాన్ని మీ స్వరూపంగా భావించడం వల్లనే మీరు బాధపడుతున్నారు.',
    'అసంపూర్ణత భావం నుండి కోరిక ఉద్భవిస్తుంది, అది తప్పుడు భావనే.',
    'భయం అనేది వ్యక్తికి మాత్రమే ఉంటుంది. ఆత్మకు భయం తెలియదు.',
    'మీరు శరీరం కాదని తెలుసుకున్నప్పుడు, మరణం భయాన్ని కోల్పోతుంది.',
    'నొప్పి శారీరకమైనది; బాధ మానసికమైనది. అర్థం చేసుకోవడం ద్వారా మీరు బాధను అధిగమించవచ్చు.',
    'మీరు ప్రతిఘటించేది నిలిచిపోతుంది. మీరు అర్థం చేసుకున్నది కరిగిపోతుంది.',
    'ఆకాంక్ష అనేది భవిష్యత్తులోకి విసిరిన స్మృతి.',
    'స్వేచ్ఛ అనేది కోరికల నెరవేర్పు కాదు, కోరికల నుండి విముక్తి.',
    'వేదన అనేది మీరు మీ గురించి పొరపాటుగా ఉన్నారని సూచించే సంకేతం.',
    'తప్పుడు గుర్తింపు ముగిసినప్పుడు, దుఃఖం కూడా దానితో ముగుస్తుంది.',
    'ప్రపంచం అసత్యం కాదు, కానీ అది మీరు అనుకుంటున్నదానిలా కాదు. అది చైతన్యానికి ప్రతిబింబం.',
    'మీరు ఈ లోకంలో భాగమని నమ్మినప్పుడు, ఈ లోకం నిజమని అనిపిస్తుంది.',
    'చైతన్యం నిశ్చలంగా ఉన్నప్పుడు, ప్రపంచం కూడా నిశ్చలంగా ఉంటుంది.',
    'ప్రపంచం అనుభవించబడినంతకాలం మాత్రమే ఉంది.',
    'మీరు ప్రపంచాన్ని వ్యక్తిగతంగా తీసుకోవడం ద్వారా దానికి వాస్తవత్వం ఇస్తారు.',
    'లోకానికి చైతన్యం నుండి వేరుగా స్వతంత్రమైన ఉనికి లేదు.',
    'నిజం సులభం; మాయ అయితే సంక్లిష్టం.',
    'ప్రపంచం మంచి లేదా చెడు కాదు. అది కేవలం మీ అవగాహనను ప్రతిబింబిస్తుంది.',
    'మీరు \'నిజ జీవితమని\' పిలిచేది అనుభూతుల ప్రవాహం.',
    'ప్రపంచం ఒక ప్రదర్శన, కానీ చైతన్యం దానిని సీరియస్‌గా తీసుకుంటుంది.',
    'గురు మీకు కొత్తదాన్ని ఇవ్వరు. ఆయన అసత్యాన్ని తొలగిస్తారు.',
    'కృప అనేది ఒక సంఘటన కాదు; అది మీ సహజ స్వభావం.',
    'మీరు సిద్ధంగా ఉన్నప్పుడు, ఆ ఉపదేశం మీకు దొరుకుతుంది.',
    'గురు చూపిస్తాడు, కానీ చూడాల్సింది మీరు.',
    'బోధనను నమ్మండి, కానీ దానిని మీరే నిర్ధారించుకునే వరకు.',
    'గురువుపై విశ్వాసం అంటే మీ స్వయంలొ విశ్వాసం.',
    'పదాలు కేవలం సూచికలు మాత్రమే. వాటికి ఆవలంబించకండి.',
    'ఉన్నతమైన బోధన నిశ్శబ్దం.',
    'నిజమైన గురువు అహంకారాన్ని ఆదరించడు; దానిని నాశనం చేస్తాడు.',
    'అర్థం సంపూర్ణమయ్యినప్పుడు, గురువు అదృశ్యమవుతాడు.',
    'మోక్షం కాలంలో సాధించదగిన విజయమేమీ కాదు. అది కాలాతీతమైనదాన్ని గుర్తించడం.',
    'నీవు ఇప్పుడు స్వతంత్రుడివి, కానీ నీవు నీకు బంధించబడినట్లు ఊహించుకుంటున్నావు.',
    'స్వేచ్ఛ అనేది మీరు ఇష్టపడినదాన్ని చేయడం కాదు, కానీ కోరికల చేత బలవంతం చేయబడకపోవడం.',
    '\'నేను\' అనే భావం లేనప్పుడు, బంధనం ఉండదు.',
    'మోక్షం అనేది అన్వేషణకు ముగింపు.',
    'ముక్తుడికి ఏమీ జరగదు, ఎందుకంటే అది జరగడానికి ఎవరూ లేరు.',
    'విముక్తి స్థితి సాధారణం, సహజం, మరియు గమనించబడని దాంటివి.',
    'మీరు స్వతంత్రులు కాలేదు; మీరు ఎప్పుడూ బంధించబడలేదని తెలుసుకుంటారు.',
    'అత్యున్నత స్థితి అనేది అసలు స్థితి కాదు.',
    'అజ్ఞానం ముగిసినప్పుడు, ఏదైనా ప్రత్యేకమైనది జరగదు — సత్యం సులభంగా ప్రత్యక్షమవుతుంది.',
    'మీరు వాస్తవికత యొక్క ఒక భాగం కాదు. మీరు వాస్తవికత స్వయంగా.',
    'ఏది కనిపిస్తుందో అది అదృశ్యమవుతుంది. కనిపించని దాని అదృశ్యం కావడం అసంభవం.',
    'అఖండం గుణరహితం అయినప్పటికీ, అన్ని గుణాలు దానినుంచి ఉద్భవిస్తాయి.',
    'నీవు పరమార్థాన్ని ఒక వస్తువుగా తెలుసుకోలేవు, ఎందుకంటే నీవే అది.',
    'ఆత్మ అనుభవించబడదు; అది అనుభవించేది.',
    'ప్రశ్నలు అన్నీ నిశ్చలమయ్యినప్పుడు, సత్యం నిలిచివుంటుంది.',
    'మీకు ఏమీ జోడించాల్సిన అవసరం లేదు; కేవలం తప్పుడు ఆలోచనలను తొలగించాలి.',
    'మీ నిజమైన స్వరూపం అంగీకారానికి, నిరాకరణకు అతీతమైనది.',
    'నిశ్శబ్దంగా ఉండి పరిశీలించండి — అంతే.',
    'నిజం సులభం, కానీ మనసు ఆ సులభతను అంగీకరించదు.',
    'ఉనికిని అనుభూతి చేసే భావంలో ఉండి, అది కూడా కరిగిపోయే వరకు.',
    'నిజాన్ని పట్టుకోవడానికి ప్రయత్నించకండి; అబద్ధం తుడిచిపెట్టుకుపోవనివ్వండి.',
    'అవగాహనే మూలం, అనుభవం కాదు.',
    'నిజమైనది ఎప్పుడూ సన్నిధిలోనే ఉంటుంది.',
    'నీవు కాలానికి ముందు ఉన్నవాడివి.',
    'వాస్తవంలో తప్పేమీ లేదు; మీ ఆలోచనలే తప్పు.',
    'శోధకుడు కనుమరుగైతే, అన్వేషితం ప్రత్యక్షమవుతుంది.',
    'ఆలోచనల నుండి ఖాళీగా ఉండండి.',
    'మీరు సాక్షి, సాక్ష్యం కాదు.',
    'నీవు ఉన్నావు — అదే చాలు.',
  ],

  [
    Article(
        heading: 'నేను ఎవరు? - ప్రాథమిక ప్రశ్న',
        body: 'నిసర్గదత్త మహారాజ్ యొక్క ఉపదేశం "నేను ఎవరు?" అనే ప్రాథమిక ప్రశ్న చుట్టూ తిరిగింది. ఆయన తన శిష్యులను అన్ని భావనలు మరియు గుర్తింపుల కంటే మించి వారి నిజమైన స్వరూపాన్ని పరిశీలించడానికి నిరంతరం ప్రేరేపించేవారు. \n\n"మీరు మీను మీరు అనుకుంటున్నట్లుగా కాదు," ఆయన చెప్పేవారు. "మీరు ఏమిటి అనేది కనుగొనండి." ఈ పరిశోధన ఒక బుద్ధి వ్యాయామం కాదు, \'నేను\' భావన యొక్క మూలాన్ని నేరుగా విచారించడమే.\n\nమహారాజ్ మనం సాధారణంగా శరీరం, మనసు, ఆలోచనలు, భావాలు మరియు జీవితంలో పోషించే వివిధ పాత్రలతో మనలను గుర్తించుకుంటామని బోధించారు. కానీ ఇవన్నీ చైతన్యంలో కనిపించే వస్తువులే. మేము కనిపించే అవగాహన, ఆ వస్తువులు కాదు. \n\nఆత్మ పరిశీలన ప్రక్రియ మీకు సంబంధించినది కాని అన్ని విషయాలను తిరస్కరించడం ద్వారా జరుగుతుంది - "నేను శరీరం కాదు, నేను మనస్సు కాదు, నేను ఆలోచనలు కాదు" - మీకు మిగిలినది ఏమిటో తెలుసుకునే వరకు. మిగిలినది శుద్ధ అవగాహన, శుద్ధ సత్యం, మీ నిజమైన స్వభావం.\n\n"మీరు ఏమిటి అనేది తెలుసుకోవాలంటే, మీరు ముందుగా మీరు ఏమి కాదు అనేది పరిశీలించి తెలుసుకోవాలి," మహారాజ్ చెప్పారు. ఈ తొలగింపు ప్రక్రియ మీ శుద్ధ అవగాహనగా ఉన్న ప్రాథమిక స్వభావాన్ని గుర్తించడానికి దారితీస్తుంది, అన్ని లక్షణాలు మరియు పరిమితుల కంటే మించి.\n\n"నేను ఎవరు?" అనే ప్రశ్నను తీవ్రమైన నిజాయితీతో మరియు నిబద్ధతతో అన్వేషించాలి. ఇది మేధస్సుతో అర్థం చేసుకోవడం సరిపోదు; ఇది మీ ఉనికిలో ప్రతి క్షణాన్ని వ్యాపించాల్సిన ఒక జీవించు విచారణగా మారాలి, దాని ద్వారా ప్రత్యేక వ్యక్తిగా ఉండే అబద్ధ భావన పూర్తిగా కరిగిపోతుంది.'
    ),
    Article(
        heading: 'చేతనత యొక్క స్వభావం',
        body: 'నిసర్గదత్త మహారాజ్ చైతన్యాన్ని వివరిస్తున్నప్పుడు ఒక ప్రత్యేకమైన పద్ధతిని అనుసరించారు, అది లోతైనదిగా మరియు అందరికీ అర్థమయ్యేలా ఉంది. ఆయన వ్యక్తిగత చైతన్యాన్ని (అతను "నేను ఉన్నాను" అనుభూతి అని పిలిచేవాడు) మరియు అనుభవానికి మించిన పరమ చైతన్యాన్ని వేరు చేసారు.\n\n"నేను ఉన్నాను" అనేది చైతన్యంలోని మొదటి చలనం, ఇది అన్ని ఇతర అనుభవాలకు పుట్టిన ప్రాథమిక భావన. మహారాజ్ ఈ శుద్ధ "నేను ఉన్నాను" అనుభూతిని "నేను ఇది" లేదా "నేను అది" వంటి అదనపు భావనలతో కలిపకుండా ఉంచాలని బోధించారు.\n\n"మీలో ఉన్న చైతన్యం మరియు నాలో ఉన్న చైతన్యం, స్పష్టంగా రెండు, ఒకటే" అని ఆయన చెప్పేవాడు. ఈ అవగాహన వేరుపడినదని భావించే మాయను కరిగించి, అన్ని స్పష్టమైన వైవిధ్యాలకు వెనుక ఉన్న ఐక్యతను ఆవిష్కరిస్తుంది.\n\nమహారాజ్ చైతన్యం మెదడు లేదా శరీరం ద్వారా ఉత్పత్తి కావడం లేదని వివరించారు. బదులుగా, శరీరం మరియు మెదడు చైతన్యంలో కనిపిస్తాయి. చైతన్యం వ్యక్తిగతం కాదు; ఇది విశ్వవ్యాప్తం, మరియు మనం వ్యక్తిగత చైతన్యంగా తీసుకునేది ఈ విశ్వ చైతన్యానికి కేవలం ప్రతిబింబం మాత్రమే. \n\nఅత్యంత వాస్తవం చైతన్యాన్ని మించినది - ఇది చైతన్యం స్వయంగా కనిపించి, మాయమవ్వే ఆది. ఇది మీ నిజమైన స్వభావం, చైతన్యానికి ముందు, ఉనికి మరియు అనుబంధానికి ముందు. \n\n"మీరు పరమ వాస్తవం," మహారాజ్ ప్రకటించేవారు. "చిన్న మనస్సు కాకండి." ఈ పరమ వాస్తవాన్ని ఒక వస్తువుగా తెలుసుకోవడం సాధ్యం కాదు ఎందుకంటే మీరు అదే. మీరు మీ గురించి ఆలోచించే అన్ని విషయాల క్షయంతో మాత్రమే ఇది గుర్తించబడుతుంది.'
    ),
    Article(
        heading: 'వ్యక్తి యొక్క మాయా',
        body: 'నిసర్గదత్త మహారాజ్ యొక్క అత్యంత విపరీతమైన ఉపదేశాలలో ఒకటి వ్యక్తి యొక్క మాయా స్వరూపం గురించి. ఆయన ఇలా చెప్పేవారు, "మీరు మీను ఒక వ్యక్తిగా భావిస్తారు, కానీ మీరు ఎప్పుడూ ఒక వ్యక్తిగా జన్మించలేదు."\n\nవ్యక్తి అనేది కేవలం జ్ఞాపకాలు, ఆలోచనలు మరియు గుర్తింపుల సమాహారం, ఇవి ఒక స్పష్టమైన కొనసాగింపును సృష్టిస్తాయి. కానీ దగ్గరగా పరిశీలించినప్పుడు, వ్యక్తి అని పిలవబడే ఏదీ స్థిరమైన అస్తిత్వం లేదు. ఇది ఒక సినిమాకి సమానం - వ్యక్తిగత ఫ్రేమ్‌లు కదలిక మరియు కథ యొక్క మాయను సృష్టిస్తున్నాయి.\n\nమహారాజ్ చెప్పారు, వ్యక్తి ఒక మానసిక నిర్మాణం, స్వతంత్ర వాస్తవం లేని భావనల సమూహం. "మీరు ఏమి అనుకుంటున్నారో, మీరు ఆ కాదు," అని ఆయన నొక్కి చెప్పారు. వ్యక్తి మీలో (చైతన్యం) కనిపిస్తుంది కానీ మీరు వ్యక్తి కాదు. \n\nఈ అవగాహన విముక్తి కలిగించేది ఎందుకంటే, ఇది వ్యక్తి యొక్క అన్ని సమస్యలు, పరిమితులు మరియు బాధలు కూడా మాయ మాత్రమే అని అర్థం. మీరు వ్యక్తి కాదు అని గ్రహించినప్పుడు, మీరు వ్యక్తి యొక్క విధి, karma మరియు పరిస్థితుల నుండి విముక్తి పొందుతారు.\n\n"మీరు perceivable చేసినది మీది కాదు. మీరు perceivable చేసినది మీతో సంబంధం లేదు," మహారాజ్ చెప్పేవారు. ఇది మనం సాధారణంగా మనదిగా భావించే శరీరం, మనసు, ఆలోచనలు మరియు భావనలు కూడా కలిగి ఉంటుంది.\n\nమీరు వ్యక్తి కాదు అని గుర్తించడం తాత్త్విక స్థితి కాదు, కానీ నిజమైన ఆత్మ-అన్వేషణ ద్వారా వచ్చే ప్రత్యక్ష అవగాహన. ఈ గుర్తింపు స్థిరంగా మరియు అచలంగా మారినప్పుడు, మీరు మీ నిజమైన స్వరూపంగా నివసిస్తారు - శుద్ధ అవగాహన, శుద్ధ అస్తిత్వం, అన్ని వ్యక్తిగత పరిమితుల కంటే మించి.'
    ),
    Article(
        heading: 'ప్రేమ మరియు జ్ఞానం - సత్యం యొక్క రెండు రెక్కలు',
        body: 'నిసర్గదత్త మహారాజ్ తన ప్రసిద్ధ వాక్యంలో ఆత్మవిశ్లేషణ యొక్క పరadoxను అందంగా వ్యక్తం చేశారు: "జ్ఞానం నాకు నేను ఏమీ కాదని చెబుతుంది. ప్రేమ నాకు నేను అన్నీ అని చెబుతుంది. ఈ రెండు మధ్య నా జీవితం ప్రవహిస్తుంది."\n\nజ్ఞానం అనేది మీ నిజమైన స్వభావాన్ని శుద్ధమైన అవగాహనగా గుర్తించడం, ఇది లక్షణాలు, రూపం, గుణాలు లేని - మానసికంగా పట్టుకోగలిగే ఏమీ లేదు. ఈ దృక్పథం నుండి, మీరు శూన్యం, అన్ని అనుభవాలు కనిపించే ఖాళీ.\n\nప్రేమ, మరోవైపు, ఈ అదే అవగాహన అన్ని కనిపించే వాటి యొక్క అసలు సారాన్ని గుర్తించడం. మీరు ఏదైనా నుండి వేరుగా లేరు; మీరు అనేక రూపాల్లో కనిపించే ఒకటే. ఇది మీ స్వయంగా అన్ని ఉనికిని ఆప్యాయంగా స్వీకరించే ప్రేమ.\n\nఇవి విరుద్ధమైన సత్యాలు కాదు, కానీ ఒకే ఆత్మవిశ్లేషణ యొక్క రెండు కోణాలు. అనంతం ఖాళీ మరియు సంపూర్ణత, శూన్యం మరియు సమస్తం, పరమాత్మ మరియు అంతరాత్మ. \n\n"నేను లోపల చూడగానే నేను శూన్యం అని తెలుసుకోవడం, అది జ్ఞానం. నేను బయట చూడగానే నేను సమస్తం అని తెలుసుకోవడం, అది ప్రేమ," మహారాజ్ వివరించారు. ఈ ద్వంద్వ గుర్తింపు సంపూర్ణ అవగాహన యొక్క లక్షణం.\n\nఈ అవగాహన ఆధారంగా జీవించడం అంటే, మీరు శూన్యం (ఏది కాదు) అని తెలుసుకోవడం ద్వారా శాంతిలో స్థిరంగా ఉండడం మరియు మీ స్వంత రూపంలో కనిపించే సమస్తాన్ని ప్రేమించడం. ఇది సాకారమైన జీవి యొక్క సహజ స్థితి - స్వీయాన్ని కోల్పోయి, అందరికీ ప్రేమతో నిండి ఉండటం.'
    ),
    Article(
        heading: 'జన్మ మరియు మరణం మించిపోయి',
        body: 'నిసర్గదత్త మహారాజ్ మరణం మరియు అమరత్వంపై చెప్పిన ఉపదేశాలు ప్రత్యేకంగా శక్తివంతమైనవి మరియు సాంత్వన కలిగించేలా ఉన్నాయి. "నిజం చనిపోదు, అసత్యం ఎప్పుడూ జీవించలేదు" అని ఆయన ఖచ్చితత్వంతో చెప్పేవారు.\n\nఅతని దృష్టిలో, మేము పుట్టడం మరియు చనడం అని పిలిచే వాటి అన్నీ మన చైతన్యంలో ఉన్న కేవలం రూపాలు, కలలలోని దృశ్యాల్లా ఉన్నాయి. శరీరం పుట్టి చనిపోతుంది, కానీ మీరు - శరీరం కనిపించే అవగాహన - ఎప్పుడూ పుట్టరు కాబట్టి చనిపోవడం అసాధ్యం.\n\n"మీరు మరణాన్ని భయపడుతున్నారు ఎందుకంటే మీరు మీను తెలుసుకోలేదు" అని మహారాజ్ సూచించేవారు. "నిజమైన మీరు మరణరహితుడు." ఈ మరణ భయం మృత శరీరంతో ఐక్యమవడం వల్ల వస్తుంది, అమర చైతన్యంగా మీను గుర్తించకపోవడం వల్ల.\n\nమహారాజ్ మేము నిజంగా పుట్టడం లేదా చనడం అనుభవించలేదని బోధించారు. మాకు గతం యొక్క జ్ఞాపకాలు మరియు భవిష్యత్తు గురించి ఊహలు ఉన్నాయి, కానీ మన నిజమైన అనుభవం ఎప్పుడూ ప్రస్తుత క్షణంలో ఉన్న అవగాహనతో ఉంటుంది. ఈ అవగాహన ఎప్పుడూ ఉంది మరియు ఎప్పుడూ ఉంటుంది.\n\nమీ మరణరహిత స్వభావాన్ని అర్థం చేసుకోవడం ఒక నమ్మకం లేదా సాంత్వన కాదు, కానీ ఒక ప్రత్యక్ష గుర్తింపు. మీరు నిజంగా మీను శుద్ధ అవగాహనగా తెలుసుకుంటే, మరణ భయం కేవలం అంతరించిపోతుంది ఎందుకంటే మీరు మరణించగలిగే ఏమీ లేదని గ్రహిస్తారు.\n\n"మీ బలహీనత మీకు ఈ ప్రపంచంలో జన్మించారని ఉన్న నమ్మకానికి కారణం," అని అతను చెప్పేవాడు. వాస్తవానికి, ప్రపంచం మీలో కనిపిస్తుంది; మీరు ప్రపంచంలో కనిపించడం లేదు. ఈ ప్రాథమిక అవగాహన మార్పు మీ జీవితానికి మరియు మరణానికి సంబంధించిన మీ మొత్తం సంబంధాన్ని మార్చుతుంది.\n\nఈ ఉపదేశం యొక్క ప్రాయోగిక అర్థం విస్తృతమైన స్వేచ్ఛ మరియు భయంలేని స్థితి. మీరు మీను మరణం లేని వాస్తవంగా తెలుసుకున్నప్పుడు, మీరు సంపూర్ణంగా జీవించగలరు మరియు మీ సహజ ఆనందం మరియు శాంతిని మబ్బుగా కప్పిపుచ్చే మరణం యొక్క నీడ లేకుండా పూర్తిగా ప్రేమించగలరు.'
    ),
  ],
);
